commit 37b84fb6425485bd5f2ab0396885a9a9d616e47c
Author: Dan LaRocque <dalaro@hopcount.org>
Date:   Fri May 24 15:33:05 2013 -0400

    Remove unchecked cast in AbstractElement#equals()

    Modify AbstractElement's equals() method to eliminate potential
    unchecked casts while attempting to stay as close as possible to the
    behavior of the original implementation.

    closes #286

diff --git a/titan-core/src/main/java/com/thinkaurelius/titan/graphdb/internal/AbstractElement.java b/titan-core/src/main/java/com/thinkaurelius/titan/graphdb/internal/AbstractElement.java
index 8f69d4a..339f4a0 100644
--- a/titan-core/src/main/java/com/thinkaurelius/titan/graphdb/internal/AbstractElement.java
+++ b/titan-core/src/main/java/com/thinkaurelius/titan/graphdb/internal/AbstractElement.java
@@ -33,12 +33,17 @@ public abstract class AbstractElement implements InternalElement {

     @Override
     public boolean equals(Object other) {
-        if (this==other) return true;
-        else if (other==null) return false;
-        if (((this instanceof TitanVertex) && (other instanceof TitanVertex)) ||
-                ((this instanceof TitanEdge) && (other instanceof TitanEdge)))
-            return getID()==((AbstractElement)other).getID();
-        else return false;
+        if (this==other) {
+            return true;
+        } else if (other==null) {
+            return false;
+        } else if (this instanceof TitanVertex && other instanceof TitanVertex) {
+            return getId().equals(((TitanVertex)other).getId());
+        } else if (this instanceof TitanEdge && other instanceof TitanEdge) {
+            return getId().equals(((TitanEdge)other).getId());
+        } else {
+            return false;
+        }
     }

